(async function () {
'use strict';
const h = value => escapeHTML(value);
const SECTIONS = [['home','HOME','خانه'],['money','مدیریت سرمایه','مدیریت سرمایه'],['mind','مدیریت روانی','ذهن آرام، تصمیم بهتر'],['technical','تکنیکال','تحلیل و یادگیری'],['plan','پلن معاملاتی','مسیر شخصی معامله'],['journal','ژورنال‌نویسی','روایت معاملات شما'],['accounts','حساب‌ها','مدیریت حساب‌های معاملاتی']];
const DEFAULT_SYMBOLS = ['XAUUSD','EURUSD','DXY','GBPUSD'];
const freshState = () => ({version:1,accounts:[],trades:[],notes:[],costs:[],steps:[],symbols:[...DEFAULT_SYMBOLS],checklist:[{id:'plan',text:'معامله با پلن من مطابقت دارد',done:false},{id:'risk',text:'ریسک و حد ضرر را مشخص کرده‌ام',done:false},{id:'mind',text:'آرام هستم و برای جبران ضرر معامله نمی‌کنم',done:false}],checklistDate:'',settings:{rate:0,rateAt:'',currency:'USD',feed:'',autoRate:true,rateSource:'manual',theme:'light'},quotes:[],quotesAt:''});
const escapeHTML = value => String(value ?? '').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
function fixedDate(date, offset) { return new Date(date.getTime()+offset*3600000); }
function dayKey(date=new Date()) { return fixedDate(date,3.5).toISOString().slice(0,10); }
function sessionAt(date=new Date()) {
  const d=fixedDate(date,-4), minutes=d.getUTCHours()*60+d.getUTCMinutes();
  if(minutes>=1380||minutes<240)return 'آسیا';
  if(minutes>=360&&minutes<420)return 'فرانکفورت';
  if(minutes>=420&&minutes<540)return 'لندن';
  if(minutes>=720&&minutes<840)return 'نیویورک';
  return 'None';
}
function clockAt(date,offset) {return fixedDate(date,offset).toISOString().slice(11,19);}
function filterTrades(trades,{account='',start='',end=''}={}) {return trades.filter(t=>(!account||t.account===account)&&(!start||t.date>=start)&&(!end||t.date<=end));}
function statistics(trades) {const wins=trades.filter(t=>t.result==='TP').length;return {count:trades.length,wins,losses:trades.length-wins,winRate:trades.length?wins/trades.length*100:0,pnl:trades.reduce((s,t)=>s+t.pnl,0)};}
function accountStats(account,trades) {const result=statistics(trades.filter(t=>t.account===account.id));return {...result,balance:account.deposit+result.pnl,percent:account.deposit?result.pnl/account.deposit*100:0};}
function riskAmount(balance,percent) {if(!Number.isFinite(balance)||balance<0||!Number.isFinite(percent)||percent<=0||percent>100)throw Error('سرمایه و درصد ریسک معتبر وارد کنید.');return balance*percent/100;}
function dateRange(kind,today=dayKey()) {const d=new Date(today+'T00:00:00Z');if(kind==='week')d.setUTCDate(d.getUTCDate()-6);else if(kind==='month')d.setUTCDate(1);return {start:d.toISOString().slice(0,10),end:today};}
const validDate = s => typeof s==='string'&&/^\d{4}-\d{2}-\d{2}$/.test(s)&&!Number.isNaN(Date.parse(s))&&new Date(s).toISOString().slice(0,10)===s;
const text = (s,max=10000) => typeof s==='string'&&s.length<=max;
const finite = n => typeof n==='number'&&Number.isFinite(n)&&Math.abs(n)<=1e12;
function validateState(s) {
  const fail=()=>{throw Error('ساختار فایل پشتیبان معتبر نیست.');};
  if(!s||s.version!==1)fail();
  for(const key of ['accounts','trades','notes','costs','steps','symbols','checklist','quotes'])if(!Array.isArray(s[key])||s[key].length>20000)fail();
  for(const key of ['accounts','trades','notes','costs','steps','checklist']) {const ids=new Set();for(const row of s[key]){if(!row||!text(row.id,100)||!row.id||ids.has(row.id))fail();ids.add(row.id);}}
  for(const a of s.accounts)if(!text(a.name,200)||!text(a.type,100)||!text(a.broker,200)||!finite(a.deposit)||a.deposit<0||!validDate(a.date))fail();
  const ids=new Set(s.accounts.map(a=>a.id));
  if(!s.symbols.every(v=>text(v,30)&&/^[A-Z0-9._/-]+$/.test(v))||new Set(s.symbols).size!==s.symbols.length)fail();
  for(const t of s.trades)if(!ids.has(t.account)||!validDate(t.date)||!/^([01]\d|2[0-3]):[0-5]\d$/.test(t.time)||!text(t.symbol,30)||!s.symbols.includes(t.symbol)||!['TP','SL'].includes(t.result)||!finite(t.pnl)||(t.result==='TP'&&t.pnl<0)||(t.result==='SL'&&t.pnl>0)||!text(t.note)||!text(t.image,3000000)||(t.image&&!/^data:image\/(png|jpeg|webp);base64,[A-Za-z0-9+/=]+$/.test(t.image)))fail();
  for(const n of s.notes)if(!['money','mind','technical','plan','journal'].includes(n.section)||!text(n.text)||!validDate(n.date))fail();
  for(const c of s.costs)if(!text(c.title,200)||!finite(c.amount)||c.amount<0||!validDate(c.date))fail();
  for(const p of s.steps)if(!text(p.text,500))fail();
  for(const c of s.checklist)if(!text(c.text,500)||typeof c.done!=='boolean')fail();
  if(!text(s.checklistDate,10)||(s.checklistDate&&!validDate(s.checklistDate)))fail();
  if(!s.settings||!finite(s.settings.rate)||s.settings.rate<0||!text(s.settings.rateAt,40)||!['USD','IRT'].includes(s.settings.currency)||!text(s.settings.feed,500)||!text(s.quotesAt,40))fail();
  if(s.settings.autoRate!==undefined&&typeof s.settings.autoRate!=='boolean')fail();
  if(s.settings.theme!==undefined&&!['light','dark'].includes(s.settings.theme))fail();
  if(s.settings.rateSource!==undefined&&!['manual','priceto.day','custom'].includes(s.settings.rateSource))fail();
  for(const q of s.quotes)if(!text(q.symbol,30)||!finite(q.price)||q.price<=0||!finite(q.change))fail();
  return s;
}
function validateFeed(data) {
  if(!data||!Array.isArray(data.quotes)||!data.quotes.length||data.quotes.length>100||!Number.isFinite(Date.parse(data.timestamp))||Date.parse(data.timestamp)>Date.now()+300000)throw Error('پاسخ منبع نرخ معتبر نیست.');
  const quotes=data.quotes.map(q=>{if(!DEFAULT_SYMBOLS.includes(q.symbol)||!finite(q.price)||q.price<=0||!finite(q.change))throw Error('نرخ دریافتی معتبر نیست.');return {symbol:q.symbol,price:q.price,change:q.change};});
  if(new Set(quotes.map(q=>q.symbol)).size!==quotes.length)throw Error('نماد تکراری در پاسخ منبع.');
  if(data.usdToman!==undefined&&(!finite(data.usdToman)||data.usdToman<=0))throw Error('نرخ تومان معتبر نیست.');
  return {quotes,timestamp:data.timestamp,rate:data.usdToman};
}

let db;
function open(){return new Promise((resolve,reject)=>{let finished=false;const timer=setTimeout(()=>{finished=true;reject(Error('بازکردن حافظه بیش از حد طول کشید. پنجره‌های دیگر برنامه را ببندید و دوباره تلاش کنید.'));},8000);const fail=error=>{finished=true;clearTimeout(timer);reject(error);};let request;try{request=indexedDB.open('met-journal',1);}catch(error){fail(error);return;}request.onupgradeneeded=()=>{if(!request.result.objectStoreNames.contains('data'))request.result.createObjectStore('data');};request.onblocked=()=>fail(Error('حافظه توسط پنجرهٔ دیگری باز است؛ پنجره‌های دیگر برنامه را ببندید.'));request.onsuccess=()=>{if(finished){request.result.close();return;}finished=true;clearTimeout(timer);request.result.onversionchange=()=>request.result.close();resolve(request.result);};request.onerror=()=>fail(request.error);});}
async function load(){db=await open();return new Promise((resolve,reject)=>{const timer=setTimeout(()=>reject(Error('خواندن حافظه متوقف شد؛ صفحه را دوباره باز کنید. اطلاعات حذف نشده است.')),8000);const req=db.transaction('data').objectStore('data').get('state');req.onsuccess=()=>{clearTimeout(timer);try{resolve(req.result?validateState(req.result):freshState());}catch(e){reject(e);}};req.onerror=()=>{clearTimeout(timer);reject(req.error);};});}
function save(state){validateState(state);return new Promise((resolve,reject)=>{const tx=db.transaction('data','readwrite');tx.objectStore('data').put(state,'state');tx.oncomplete=resolve;tx.onerror=()=>reject(tx.error);tx.onabort=()=>reject(tx.error||Error('ذخیره‌سازی متوقف شد.'));});}

const xml=value=>escapeHTML(value).replace(/[\u0000-\u0008\u000b\u000c\u000e-\u001f]/g,'');
const enc=new TextEncoder();
function crc32(bytes){let crc=-1;for(const b of bytes){crc^=b;for(let i=0;i<8;i++)crc=(crc>>>1)^((crc&1)?0xedb88320:0);}return (crc^-1)>>>0;}
function zipFiles(files){const chunks=[],central=[];let offset=0;for(const [name,content] of Object.entries(files)){const n=enc.encode(name),data=typeof content==='string'?enc.encode(content):content;const crc=crc32(data);const h=new Uint8Array(30+n.length);const v=new DataView(h.buffer);v.setUint32(0,0x04034b50,true);v.setUint16(4,20,true);v.setUint16(6,0x800,true);v.setUint32(14,crc,true);v.setUint32(18,data.length,true);v.setUint32(22,data.length,true);v.setUint16(26,n.length,true);h.set(n,30);chunks.push(h,data);const c=new Uint8Array(46+n.length),cv=new DataView(c.buffer);cv.setUint32(0,0x02014b50,true);cv.setUint16(4,20,true);cv.setUint16(6,20,true);cv.setUint16(8,0x800,true);cv.setUint32(16,crc,true);cv.setUint32(20,data.length,true);cv.setUint32(24,data.length,true);cv.setUint16(28,n.length,true);cv.setUint32(42,offset,true);c.set(n,46);central.push(c);offset+=h.length+data.length;}const size=central.reduce((s,c)=>s+c.length,0),end=new Uint8Array(22),ev=new DataView(end.buffer);ev.setUint32(0,0x06054b50,true);ev.setUint16(8,central.length,true);ev.setUint16(10,central.length,true);ev.setUint32(12,size,true);ev.setUint32(16,offset,true);const all=[...chunks,...central,end],out=new Uint8Array(all.reduce((s,c)=>s+c.length,0));let cursor=0;for(const c of all){out.set(c,cursor);cursor+=c.length;}return out;}
const rels=body=>`<?xml version="1.0" encoding="UTF-8" standalone="yes"?><Relationships xmlns="http://schemas.openxmlformats.org/package/2006/relationships">${body}</Relationships>`;
const rel=(id,type,target)=>`<Relationship Id="${id}" Type="http://schemas.openxmlformats.org/officeDocument/2006/relationships/${type}" Target="${target}"/>`;
const types=body=>`<?xml version="1.0" encoding="UTF-8"?><Types xmlns="http://schemas.openxmlformats.org/package/2006/content-types"><Default Extension="rels" ContentType="application/vnd.openxmlformats-package.relationships+xml"/><Default Extension="xml" ContentType="application/xml"/>${body}</Types>`;
const override=(part,type)=>`<Override PartName="/${part}" ContentType="application/vnd.openxmlformats-officedocument.${type}+xml"/>`;
function column(i){let s='';for(i++;i;i=Math.floor((i-1)/26))s=String.fromCharCode(65+(i-1)%26)+s;return s;}
function excelBytes(title,headers,rows){const data=[[title],headers,...rows];const sheet=data.map((r,i)=>`<row r="${i+1}">${r.map((v,j)=>typeof v==='number'&&Number.isFinite(v)?`<c r="${column(j)}${i+1}"><v>${v}</v></c>`:`<c r="${column(j)}${i+1}" t="inlineStr"><is><t xml:space="preserve">${xml(v)}</t></is></c>`).join('')}</row>`).join('');return zipFiles({'[Content_Types].xml':types(override('xl/workbook.xml','spreadsheetml.sheet.main')+override('xl/worksheets/sheet1.xml','spreadsheetml.worksheet')),'_rels/.rels':rels(rel('rId1','officeDocument','xl/workbook.xml')),'xl/workbook.xml':'<workbook xmlns="http://schemas.openxmlformats.org/spreadsheetml/2006/main" xmlns:r="http://schemas.openxmlformats.org/officeDocument/2006/relationships"><sheets><sheet name="گزارش" sheetId="1" r:id="rId1"/></sheets></workbook>','xl/_rels/workbook.xml.rels':rels(rel('rId1','worksheet','worksheets/sheet1.xml')),'xl/worksheets/sheet1.xml':`<worksheet xmlns="http://schemas.openxmlformats.org/spreadsheetml/2006/main"><sheetViews><sheetView workbookViewId="0" rightToLeft="1"/></sheetViews><cols><col min="1" max="${headers.length}" width="24" customWidth="1"/></cols><sheetData>${sheet}</sheetData></worksheet>`});}
const paragraph=text=>`<w:p><w:pPr><w:bidi/></w:pPr><w:r><w:rPr><w:rFonts w:ascii="Arial" w:hAnsi="Arial" w:cs="Arial"/><w:rtl/></w:rPr><w:t xml:space="preserve">${xml(text)}</w:t></w:r></w:p>`;
function wordBytes(title,headers,rows){const table=[headers,...rows].map(row=>`<w:tr>${row.map(value=>`<w:tc><w:tcPr><w:tcW w:w="${Math.floor(9360/headers.length)}" w:type="dxa"/></w:tcPr>${paragraph(value)}</w:tc>`).join('')}</w:tr>`).join('');return zipFiles({'[Content_Types].xml':types(override('word/document.xml','wordprocessingml.document.main')),'_rels/.rels':rels(rel('rId1','officeDocument','word/document.xml')),'word/document.xml':`<?xml version="1.0" encoding="UTF-8"?><w:document xmlns:w="http://schemas.openxmlformats.org/wordprocessingml/2006/main"><w:body>${paragraph(title)}<w:tbl><w:tblPr><w:bidiVisual/><w:tblW w:w="9360" w:type="dxa"/><w:tblBorders><w:top w:val="single" w:sz="4"/><w:left w:val="single" w:sz="4"/><w:bottom w:val="single" w:sz="4"/><w:right w:val="single" w:sz="4"/><w:insideH w:val="single" w:sz="4"/><w:insideV w:val="single" w:sz="4"/></w:tblBorders></w:tblPr><w:tblGrid>${headers.map(()=>`<w:gridCol w:w="${Math.floor(9360/headers.length)}"/>`).join('')}</w:tblGrid>${table}</w:tbl><w:sectPr><w:pgSz w:w="11906" w:h="16838"/><w:pgMar w:top="1200" w:right="1273" w:bottom="1200" w:left="1273"/></w:sectPr></w:body></w:document>`});}
function download(content,name,type){const url=URL.createObjectURL(new Blob([content],{type})),a=document.createElement('a');a.href=url;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(url),10000);}
function exportReport(format,title,headers,rows){if(format==='pdf'){const area=document.getElementById('print-report');area.innerHTML=`<h1>${escapeHTML(title)}</h1><p>MET · THE PERSIAN HUNTER</p><table><thead><tr>${headers.map(h=>`<th>${escapeHTML(h)}</th>`).join('')}</tr></thead><tbody>${rows.map(r=>`<tr>${r.map(v=>`<td>${escapeHTML(v)}</td>`).join('')}</tr>`).join('')}</tbody></table>`;window.print();return;}const isExcel=format==='xlsx';download(isExcel?excelBytes(title,headers,rows):wordBytes(title,headers,rows),`MET-${new Date().toISOString().slice(0,10)}.${format}`,isExcel?'application/vnd.openxmlformats-officedocument.spreadsheetml.sheet':'application/vnd.openxmlformats-officedocument.wordprocessingml.document');}

const DOLLAR_RATE_URL='https://api.priceto.day/v1/latest/irr/usd';
function parseDollarRate(data,now=Date.now()) {
  if(!data||data.success!==true||typeof data.price!=='number'||!Number.isFinite(data.price)||data.price<=0||data.price>1e12||typeof data.time!=='string')throw Error('پاسخ منبع نرخ دلار معتبر نیست.');
  const time=Date.parse(data.time);
  if(!Number.isFinite(time)||time>now+300000)throw Error('زمان نرخ دلار معتبر نیست.');
  if(now-time>48*3600000)throw Error('نرخ دریافتی بیش از ۴۸ ساعت قدیمی است؛ نرخ قبلی حفظ شد.');
  return {rate:data.price/10,rateAt:new Date(time).toISOString(),rateSource:'priceto.day'};
}
async function fetchDollarRate(fetcher=fetch,now=Date.now()) {
  const controller=new AbortController(),timer=setTimeout(()=>controller.abort(),10000);
  try {
    const response=await fetcher(DOLLAR_RATE_URL,{signal:controller.signal,cache:'no-store',credentials:'omit',referrerPolicy:'no-referrer'});
    if(!response.ok)throw Error('منبع نرخ دلار در دسترس نیست.');
    return parseDollarRate(await response.json(),now);
  } finally {clearTimeout(timer);}
}

const brandIcon='data:image/png;base64,';
const paths={home:'M3 10 12 3l9 7M5 9v12h5v-7h4v7h5V9',money:'M3 5h18v14H3zM3 9h18M15 13h3',mind:'M9 18h6M9 21h6M8 15a7 7 0 1 1 8 0v3H8z',technical:'M4 20V4M4 20h17M7 15l4-5 4 2 5-7',plan:'M4 4h6v6H4zM14 14h6v6h-6zM10 7h7v7',journal:'M5 3h14v18H5zM8 7h8M8 11h8M8 15h5',accounts:'M4 21v-9h16v9M2 8l10-5 10 5H2M8 12v9M16 12v9',plus:'M12 5v14M5 12h14',arrow:'M18 12H6m5-5-5 5 5 5',settings:'M12 8a4 4 0 1 0 0 8 4 4 0 0 0 0-8M12 2v3M12 19v3M2 12h3M19 12h3M5 5l2 2M17 17l2 2M5 19l2-2M17 7l2-2',download:'M12 3v12m-5-5 5 5 5-5M4 16v5h16v-5',check:'m5 12 4 4L19 6',clock:'M12 8v5l3 2M22 12a10 10 0 1 1-20 0 10 10 0 0 1 20 0',close:'m6 6 12 12M6 18 18 6',edit:'m4 16 12-12 4 4L8 20H4v-4M14 6l4 4',trash:'M4 6h16M9 6V3h6v3M6 6l1 15h10l1-15M10 10v7M14 10v7',menu:'M4 6h16M4 12h16M4 18h16'};
const icon=(name,cls='')=>`<svg class="icon ${cls}" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.65" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true"><path d="${paths[name]||paths.journal}"/></svg>`;
const nf=new Intl.NumberFormat('fa-IR',{maximumFractionDigits:2});
let state,tab='home',filters={account:'',...dateRange('month')},busy=false,feedBusy=false,rateBusy=false,rateError='',toastTimer;
const root=document.getElementById('app'),modal=document.getElementById('modal');
const n=v=>nf.format(v);
const accountName=id=>state.accounts.find(a=>a.id===id)?.name||'حساب حذف‌شده';
function money(v){if(state.settings.currency==='IRT')return state.settings.rate?`${n(v*state.settings.rate)} <small>تومان</small>`:'<small>ابتدا نرخ تومان را ثبت کنید</small>';return `<bdi>$${new Intl.NumberFormat('en-US',{maximumFractionDigits:2}).format(v)}</bdi>`;}
function plainMoney(v){return state.settings.currency==='IRT'&&state.settings.rate?v*state.settings.rate:v;}
const currencyTitle=()=>state.settings.currency==='IRT'&&state.settings.rate?'تومان':'USD';
const persianDate=date=>new Intl.DateTimeFormat('fa-IR',{dateStyle:'medium',timeZone:'UTC'}).format(new Date(date+'T12:00:00Z'));
const empty=(text,action='',label='')=>`<div class="empty">${icon('journal')}<p>${text}</p>${action?`<button class="text-button" data-action="${action}">${label} ${icon('arrow')}</button>`:''}</div>`;
const btn=(action,label,cls='button',extra='')=>`<button class="${cls}" data-action="${action}" ${extra}>${label}</button>`;
const exportButtons=type=>`<div class="export-buttons" aria-label="خروجی گزارش">${['xlsx','docx','pdf'].map(f=>btn('export',f==='xlsx'?'Excel':f==='docx'?'Word':'PDF','small-button',`data-type="${type}" data-format="${f}"`)).join('')}</div>`;
const sectionHeader=(title,other='')=>`<div class="section-head"><h2>${title}</h2>${other}</div>`;
function toast(message){clearTimeout(toastTimer);const el=document.getElementById('toast');el.textContent=message;el.classList.add('show');toastTimer=setTimeout(()=>el.classList.remove('show'),4500);}
async function commit(mutator){if(busy)throw Error('ذخیره‌سازی قبلی هنوز تمام نشده است.');busy=true;try{const next=JSON.parse(JSON.stringify(state));mutator(next);await save(next);state=next;render();}finally{busy=false;}}
function rateStatus(){const {rate,rateAt,rateSource,autoRate}=state.settings;const age=Date.now()-Date.parse(rateAt);const source=rateSource==='priceto.day'?'آنلاین · priceto.day':rateSource==='custom'?'API اختصاصی':'دستی';const base=rate?`هر دلار ${n(rate)} تومان · ${source} · ${h(new Date(rateAt).toLocaleString('fa-IR'))}${age>48*3600000?' · نرخ قدیمی':''}`:'هنوز نرخ تبدیل ثبت نشده است';return `${base}${rateBusy?' · در حال دریافت…':rateError?' · '+h(rateError):autoRate!==false?' · دریافت خودکار فعال':''}`;}
function updateRateStatus(){const el=document.getElementById('rate-status');if(el)el.innerHTML=rateStatus();}
async function refreshDollarRate(manual=false){if(rateBusy||(!manual&&state.settings.autoRate===false))return;if(!navigator.onLine){rateError='آفلاین؛ نرخ ذخیره‌شده تغییر نکرد';updateRateStatus();return;}rateBusy=true;rateError='';updateRateStatus();const previousAt=state.settings.rateAt;try{const result=await fetchDollarRate();if(!manual&&state.settings.autoRate===false)return;if(state.settings.rateAt!==previousAt&&state.settings.rateSource==='manual')return;await commit(s=>Object.assign(s.settings,result));if(manual)toast('نرخ دلار از وب دریافت و از ریال به تومان تبدیل شد.');}catch(error){rateError=error.name==='AbortError'?'دریافت نرخ زمان‌بر شد؛ نرخ قبلی حفظ شد':error instanceof TypeError?'اتصال به منبع نرخ ممکن نیست؛ نرخ قبلی حفظ شد':error.message;if(manual)toast(rateError);}finally{rateBusy=false;updateRateStatus();}}
function nav(){return SECTIONS.map(([id,title])=>`<button class="nav-item ${tab===id?'active':''}" data-tab="${id}" ${tab===id?'aria-current="page"':''}>${icon(id)}<span>${title}</span>${tab===id?'<span class="nav-dot"></span>':''}</button>`).join('');}
function render(){const current=SECTIONS.find(s=>s[0]===tab),dark=state.settings.theme==='dark';document.documentElement.setAttribute('data-theme',dark?'dark':'light');root.innerHTML=`<aside class="sidebar"><a class="brand sidebar-logo" href="#home" aria-label="خانه MET"><img src="${brandIcon}" alt="نشان MET" width="88" height="88"></a><div class="nav-label">فضای معاملاتی شما</div><nav aria-label="بخش‌های برنامه">${nav()}</nav><div class="sidebar-bottom"><div class="local-badge"><span class="status-dot"></span> دفتر شخصی، روی دستگاه شما</div>${btn('settings',icon('settings')+' تنظیمات و پشتیبان','nav-item')}<a href="./guide.html" class="guide-link" target="_blank" rel="noopener">راهنمای استفاده و نصب ${icon('arrow')}</a><div class="version"><span>MET WORKSPACE</span><span>V 1.2</span></div></div></aside><div class="workspace"><header class="topbar"><div class="page-context">${current[1]}<span class="connection"><i class="status-dot"></i><span id="network-label">${navigator.onLine?'آمادهٔ ثبت':'حالت آفلاین'}</span></span></div><a class="header-wordmark" href="#home" aria-label="MET — THE PERSIAN HUNTER"><strong>MET<span>JOURNAL</span></strong><small>THE PERSIAN HUNTER</small></a><div class="top-actions">${btn('currency',state.settings.currency==='USD'?'USD $':'تومان','currency-button')}${btn('theme',dark?'حالت روز':'حالت شب','theme-button',`aria-pressed="${dark}"`)}${btn('settings','تنظیمات','mobile-settings small-button')}</div></header><div class="rate-strip" aria-live="polite"><span id="rate-status">${rateStatus()}</span>${btn('refresh-rate','دریافت نرخ روز','text-button')}</div><main id="main" tabindex="-1">${tab==='home'?home():page()}</main></div>`;updateClock();}
function heading(title,subtitle,action=''){return `<div class="page-heading"><div><div class="eyebrow">دفتر شخصی معامله‌گر</div><h1>${title}</h1><p>${subtitle}</p></div>${action}</div>`;}
function home(){const stats=statistics(state.trades),capital=state.accounts.reduce((s,a)=>s+accountStats(a,state.trades).balance,0),today=state.trades.filter(t=>t.date===dayKey());return `${heading('هر معامله، یک قدم آگاهانه‌تر','به فضای معاملاتی خودت خوش آمدی. امروز را با یک پلن روشن شروع کن.',btn('new-trade',icon('plus')+' ثبت معامله','button primary'))}<div class="hero-grid"><section class="hero"><div class="hero-copy"><span class="hero-kicker">DISCIPLINE IS YOUR EDGE</span><h2>بازار را نمی‌توان کنترل کرد؛<br>تصمیم‌هایت را چرا.</h2><p>ثبت کن، مرور کن و نسخهٔ بهتری از خودت بساز.</p><button class="hero-link" data-tab="plan">مرور پلن معاملاتی ${icon('arrow')}</button></div></section><section class="card time-card"><div class="section-head"><h2>${icon('clock')} نبض زمان</h2><span class="tag" id="active-session"></span></div><div class="clock-row"><span>نیویورک <small>UTC−4 ثابت</small></span><strong id="ny-clock" dir="ltr"></strong></div><div class="clock-row"><span>تهران <small>UTC+3:30</small></span><strong id="tehran-clock" dir="ltr"></strong></div><div class="date-line"><span id="persian-date"></span><span id="gregorian-date" dir="ltr"></span></div></section></div><section class="stats-grid">${statCard('موجودی کل حساب‌ها',money(capital),'accounts','sage',`${n(state.accounts.length)} حساب معاملاتی`)}${statCard('سود و زیان خالص',money(stats.pnl),'technical','blue','بر اساس تمام معاملات ثبت‌شده',stats.pnl<0?'negative':'positive')}${statCard('نرخ موفقیت',`${n(stats.winRate)}<small>٪</small>`,'check','sand',`${n(stats.wins)} موفق از ${n(stats.count)} معامله`)}${statCard('معاملات امروز',n(today.length),'journal','lavender',persianDate(dayKey()))}</section><section class="card market-section">${sectionHeader('قیمت و نوسان آنلاین بازار',`<div class="market-tools"><span class="muted">TradingView · دادهٔ آنلاین با تأخیر احتمالی</span>${btn('refresh','به‌روزرسانی','text-button')}</div>`)}<iframe id="market-frame" title="قیمت و درصد تغییر XAUUSD، EURUSD، DXY و GBPUSD" src="./market.html?theme=${state.settings.theme==='dark'?'dark':'light'}" sandbox="allow-scripts allow-popups allow-popups-to-escape-sandbox" referrerpolicy="no-referrer" style="width:100%;height:170px;border:0;background:var(--card)"></iframe><p class="micro">نمایش آنلاین مستقیم از TradingView؛ بدون کلید API. در حالت آفلاین یا مسدودبودن سرویس، قیمت نمایش داده نمی‌شود. این نمایش نرخ تبدیل تومان را تغییر نمی‌دهد.</p>${state.quotes.length?`<details><summary>دادهٔ API اختصاصی</summary><p class="micro">${state.quotesAt?'آخرین داده: '+h(new Date(state.quotesAt).toLocaleString('fa-IR')):'منبع نرخ متصل نیست؛ نمایش آنلاین بالا مستقل از API کار می‌کند.'}</p><div class="market-grid">${DEFAULT_SYMBOLS.map((symbol,i)=>{const q=state.quotes.find(q=>q.symbol===symbol);return `<div class="market-item"><div class="market-symbol"><span class="symbol-icon ${['gold','euro','dollar','pound'][i]}">${['Au','€','$','£'][i]}</span><div><strong>${symbol}</strong><small>${['طلای جهانی','یورو / دلار','شاخص دلار','پوند / دلار'][i]}</small></div></div><div class="quote"><strong dir="ltr">${q?new Intl.NumberFormat('en-US',{maximumFractionDigits:5}).format(q.price):'—'}</strong><small class="${q?(q.change>=0?'positive':'negative'):''}">${q?`${q.change>=0?'+':''}${n(q.change)}٪`:'در انتظار اتصال'}</small></div></div>`;}).join('')}</div>${state.quotesAt?'<p class="micro">دادهٔ ذخیره‌شده ممکن است قدیمی باشد؛ زمان آخرین دریافت را بررسی کنید.</p>':''}</details>`:''}</section><div class="dashboard-grid"><section class="card performance">${sectionHeader('مسیر عملکرد شما','<span class="muted">سود و زیان تجمعی · USD</span>')}${performanceChart()}<div class="chart-caption"><span><i class="legend-dot"></i> نتیجهٔ معاملات ثبت‌شده</span><button data-tab="money" class="text-button">گزارش کامل ${icon('arrow')}</button></div></section><section class="card checklist-card">${sectionHeader('قبل از ورود به بازار',`<span class="tag">چک‌لیست روزانه</span>`)}<p class="muted">یک مکث کوتاه، یک تصمیم بهتر.</p>${state.checklist.map(c=>`<label class="check-row"><input type="checkbox" data-check="${h(c.id)}" ${c.done&&state.checklistDate===dayKey()?'checked':''}><span>${h(c.text)}</span></label>`).join('')}<div class="check-footer">${icon('mind')} انضباط، مهم‌ترین مزیت معاملاتی توست.</div></section></div><div class="dashboard-grid bottom-grid"><section class="card">${sectionHeader('آخرین معاملات',`<button data-tab="journal" class="text-button">مشاهده همه ${icon('arrow')}</button>`)}${tradeTable([...state.trades].sort(sortTrades).slice(0,5),false)}</section><section class="card quick-access">${sectionHeader('دسترسی سریع')}${[['accounts','حساب‌های من','سرمایه و عملکرد حساب‌ها'],['mind','یادداشت‌های ذهنی','برای ذهنی آرام‌تر'],['technical','دفتر تحلیل','آموخته‌ها و نکات تکنیکال']].map(([id,title,sub])=>`<button data-tab="${id}" class="quick-row"><span class="quick-icon">${icon(id)}</span><span><strong>${title}</strong><small>${sub}</small></span>${icon('arrow')}</button>`).join('')}</section></div>`;}
function statCard(label,value,symbol,color,sub,cls=''){return `<article class="card stat-card"><div class="stat-top"><span>${label}</span><span class="stat-icon ${color}">${icon(symbol)}</span></div><strong class="stat-value ${cls}">${value}</strong><small>${sub}</small></article>`;}
function performanceChart(){const trades=[...state.trades].sort((a,b)=>(a.date+a.time).localeCompare(b.date+b.time));if(!trades.length)return `<div class="chart-empty"><div class="chart-grid-lines"></div><div><span class="empty-chart-icon">${icon('technical')}</span><strong>داستان عملکردت از اولین معامله شروع می‌شود</strong><p>با ثبت معاملات، مسیر سود و زیان اینجا شکل می‌گیرد.</p>${btn('new-trade','ثبت اولین معامله','text-button')}</div></div>`;let sum=0;const values=[0,...trades.map(t=>sum+=t.pnl)],min=Math.min(...values),max=Math.max(...values),range=max-min||1;const points=values.map((v,i)=>`${40+i/(values.length-1)*600},${180-(v-min)/range*150}`).join(' ');return `<div class="chart-wrap"><svg viewBox="0 0 680 220" role="img" aria-label="نمودار سود و زیان تجمعی به دلار"><defs><linearGradient id="fill" x1="0" x2="0" y1="0" y2="1"><stop stop-color="#93b7a5" stop-opacity=".3"/><stop offset="1" stop-color="#93b7a5" stop-opacity="0"/></linearGradient></defs>${[30,80,130,180].map(y=>`<path d="M40 ${y}H640" stroke="#e8ece7" stroke-dasharray="4 5"/>`).join('')}<polygon points="40,190 ${points} 640,190" fill="url(#fill)"/><polyline points="${points}" fill="none" stroke="#4a806b" stroke-width="3"/><text x="40" y="212" font-size="12" fill="#78867f">${h(trades[0].date)}</text><text x="540" y="212" font-size="12" fill="#78867f">${h(trades[trades.length-1].date)}</text><text x="45" y="22" font-size="12" fill="#78867f">max $${max.toFixed(2)} / min $${min.toFixed(2)}</text></svg></div>`;}
const sortTrades=(a,b)=>(b.date+b.time).localeCompare(a.date+a.time);
function tradeTable(trades,actions=true){if(!trades.length)return empty('هنوز معامله‌ای در این بازه ثبت نشده است.','new-trade','ثبت معامله');return `<div class="table-scroll"><table><thead><tr><th>نماد / حساب</th><th>تاریخ و ساعت نیویورک</th><th>نتیجه</th><th>سود / زیان</th>${actions?'<th>جزئیات</th>':''}</tr></thead><tbody>${[...trades].sort(sortTrades).map(t=>`<tr><td><strong dir="ltr">${h(t.symbol)}</strong><small>${h(accountName(t.account))}</small></td><td><bdi>${h(t.date)} · ${h(t.time)}</bdi><small>${persianDate(t.date)}</small></td><td><span class="result ${t.result==='TP'?'win':'loss'}">${t.result}</span></td><td class="${t.pnl>=0?'positive':'negative'}">${money(t.pnl)}</td>${actions?`<td>${btn('edit-trade',icon('edit'),'icon-button',`data-id="${h(t.id)}" aria-label="جزئیات و ویرایش معامله"`)}${btn('delete',icon('trash'),'icon-button',`data-kind="trades" data-id="${h(t.id)}" aria-label="حذف معامله"`)}</td>`:''}</tr>`).join('')}</tbody></table></div>`;}
function page(){const titles={money:['مدیریت سرمایه','اعداد را بشناس، ریسک را مدیریت کن.'],mind:['مدیریت روانی','ذهن آرام، اجرای منظم، تصمیم آگاهانه.'],technical:['دفتر تکنیکال','از هر تحلیل، یک نکته برای فردا نگه دار.'],plan:['پلن معاملاتی','قبل از بازار، مسیر تصمیم‌هایت را مشخص کن.'],journal:['ژورنال‌نویسی','معاملاتت را ثبت کن؛ الگوهایت را بشناس.'],accounts:['حساب‌های معاملاتی','نمای یکپارچه‌ای از سرمایه و عملکرد تو.']};const [title,subtitle]=titles[tab];return heading(title,subtitle,tab==='accounts'?btn('new-account',icon('plus')+' حساب جدید','button primary'):tab==='journal'?btn('new-trade',icon('plus')+' ثبت معامله','button primary'):'')+(tab==='accounts'?accountsPage():tab==='journal'?journalPage()+notes():tab==='money'?moneyPage()+notes():tab==='plan'?planPage()+notes():notes());}
function notes(){const items=state.notes.filter(n=>n.section===tab).sort((a,b)=>b.date.localeCompare(a.date)||b.id.localeCompare(a.id));return `<section class="card notes-section">${sectionHeader('اصول، قواعد و یادگیری',`<div class="inline-actions">${exportButtons('notes')}${btn('new-note',icon('plus')+' NOTE+','button secondary')}</div>`)}${items.length?`<div class="notes-grid">${items.map(note=>`<article class="note"><div class="note-date">${persianDate(note.date)}<span>${btn('edit-note',icon('edit'),'icon-button',`data-id="${h(note.id)}" aria-label="ویرایش یادداشت"`)}${btn('delete',icon('trash'),'icon-button',`data-kind="notes" data-id="${h(note.id)}" aria-label="حذف یادداشت"`)}</span></div><p>${h(note.text)}</p></article>`).join('')}</div>`:empty('اینجا جای آموخته‌ها، قواعد و تجربه‌های شخصی شماست.','new-note','اولین یادداشت را بنویس')}</section>`;}
function accountsPage(){return `<section class="card">${sectionHeader('نمای کلی حساب‌ها',exportButtons('accounts'))}${state.accounts.length?`<div class="accounts-grid">${state.accounts.map(a=>{const st=accountStats(a,state.trades);return `<article class="account-card"><div class="section-head"><span class="stat-icon sage">${icon('accounts')}</span><span class="tag">${h(a.type)}</span></div><h2>${h(a.name)}</h2><p class="muted">${h(a.broker)} · ${persianDate(a.date)}</p><div class="account-balance">${money(st.balance)}</div><div class="account-detail"><span>سپرده اولیه</span><strong>${money(a.deposit)}</strong></div><div class="account-detail"><span>بازده معاملات</span><strong class="${st.pnl>=0?'positive':'negative'}">${n(st.percent)}٪</strong></div><div class="account-detail"><span>سود / زیان</span><strong>${money(st.pnl)}</strong></div><div class="inline-actions">${btn('edit-account','ویرایش','small-button',`data-id="${h(a.id)}"`)}${btn('delete','حذف','small-button',`data-kind="accounts" data-id="${h(a.id)}"`)}</div></article>`;}).join('')}</div>`:empty('برای شروع، حساب واقعی، دمو یا پراپ خود را اضافه کنید.','new-account','افزودن حساب')}</section>`;}
function filterPanel(){return `<form id="filters" class="filter-panel"><label>حساب<select name="account"><option value="">همه حساب‌ها</option>${state.accounts.map(a=>`<option value="${h(a.id)}" ${filters.account===a.id?'selected':''}>${h(a.name)}</option>`).join('')}</select></label><label>از تاریخ میلادی<input type="date" required name="start" value="${filters.start}"></label><label>تا تاریخ میلادی<input type="date" required name="end" value="${filters.end}"></label><button class="button secondary" type="submit">اعمال بازه</button><div class="inline-actions">${btn('range','۷ روز اخیر','small-button','data-range="week"')}${btn('range','ماه جاری','small-button','data-range="month"')}</div></form>`;}
function reportStats(){const st=statistics(filterTrades(state.trades,filters));return `<div class="report-stats"><div><small>تعداد معاملات</small><strong>${n(st.count)}</strong></div><div><small>موفق / ناموفق</small><strong><span class="positive">${n(st.wins)}</span> / <span class="negative">${n(st.losses)}</span></strong></div><div><small>نرخ موفقیت</small><strong>${n(st.winRate)}٪</strong></div><div><small>سود و زیان</small><strong class="${st.pnl>=0?'positive':'negative'}">${money(st.pnl)}</strong></div></div>`;}
function journalPage(){return `<section class="card">${sectionHeader('معاملات و گزارش بازه',`<div class="inline-actions">${btn('symbols','مدیریت نمادها','small-button')}${exportButtons('trades')}</div>`)}${filterPanel()}${reportStats()}${tradeTable(filterTrades(state.trades,filters))}</section>`;}
function moneyPage(){return `<section class="card">${sectionHeader('نتایج معاملات',exportButtons('trades'))}${filterPanel()}${reportStats()}</section><div class="dashboard-grid"><section class="card">${sectionHeader('سرمایه‌گذاری و هزینه‌ها',`<div class="inline-actions">${exportButtons('costs')}${btn('new-cost',icon('plus')+' هزینه جدید','small-button')}</div>`)}<div class="cost-total"><span>مجموع هزینه‌های این مسیر</span><strong>${money(state.costs.reduce((s,c)=>s+c.amount,0))}</strong></div>${state.costs.length?`<div class="table-scroll"><table><thead><tr><th>عنوان</th><th>تاریخ</th><th>هزینه</th><th>عملیات</th></tr></thead><tbody>${[...state.costs].sort((a,b)=>b.date.localeCompare(a.date)).map(c=>`<tr><td>${h(c.title)}</td><td>${persianDate(c.date)}</td><td>${money(c.amount)}</td><td>${btn('edit-cost',icon('edit'),'icon-button',`data-id="${h(c.id)}" aria-label="ویرایش هزینه"`)}${btn('delete',icon('trash'),'icon-button',`data-kind="costs" data-id="${h(c.id)}" aria-label="حذف هزینه"`)}</td></tr>`).join('')}</tbody></table></div>`:empty('هزینه‌های آموزش، ابزار و فعالیت معاملاتی را اینجا ثبت کنید.')}</section><section class="card">${sectionHeader('ماشین‌حساب ریسک')}<form id="risk" class="form-grid"><label>سرمایه (USD)<input name="balance" type="number" min="0" max="1000000000000" step="any" required></label><label>ریسک هر معامله (٪)<input name="percent" type="number" min="0.01" max="100" step="any" value="1" required></label><button class="button secondary">محاسبه ریسک</button><output id="risk-result" class="risk-result"></output></form><p class="micro">ابزار محاسباتی است، نه توصیهٔ سرمایه‌گذاری.</p></section></div>`;}
function planPage(){return `<section class="card">${sectionHeader('مسیر تصمیم‌گیری',`<div class="inline-actions">${exportButtons('steps')}${btn('new-step',icon('plus')+' مرحله جدید','button secondary')}</div>`)}<p class="muted">مراحل ورود تا خروج را به ترتیب تعریف کنید؛ هر مرحله قابل ویرایش و جابه‌جایی است.</p>${state.steps.length?`<div class="flow">${state.steps.map((step,i)=>`<div class="flow-unit"><article class="flow-step"><span class="step-num">${n(i+1)}</span><p>${h(step.text)}</p><div>${btn('edit-step',icon('edit'),'icon-button',`data-id="${h(step.id)}" aria-label="ویرایش مرحله"`)}${btn('move-step','↑','icon-button',`data-id="${h(step.id)}" ${i===0?'disabled':''} aria-label="انتقال به مرحله قبل"`)}${btn('delete',icon('trash'),'icon-button',`data-kind="steps" data-id="${h(step.id)}" aria-label="حذف مرحله"`)}</div></article>${i<state.steps.length-1?'<span class="flow-arrow" aria-hidden="true">↓</span>':''}</div>`).join('')}</div>`:empty('پلن شما، نقشهٔ راه شماست. اولین مرحله را تعریف کنید.','new-step','تعریف اولین مرحله')}</section>`;}
function updateClock(){const now=new Date();for(const [id,value] of Object.entries({'ny-clock':clockAt(now,-4),'tehran-clock':clockAt(now,3.5),'active-session':sessionAt(now)==='None'?'بدون سشن فعال':`سشن ${sessionAt(now)}`,'persian-date':persianDate(dayKey(now)),'gregorian-date':dayKey(now)})){const el=document.getElementById(id);if(el)el.textContent=value;}if(state?.checklistDate&&state.checklistDate!==dayKey())document.querySelectorAll('[data-check]').forEach(el=>el.checked=false);}
function field(label,name,value='',type='text',attrs=''){return `<label>${label}<input name="${name}" type="${type}" value="${h(value)}" ${attrs}></label>`;}
function textarea(label,name,value='',attrs=''){return `<label class="full">${label}<textarea name="${name}" rows="5" ${attrs}>${h(value)}</textarea></label>`;}
function openDialog(title,content,form='',id=''){modal.innerHTML=`<div class="modal-head"><h2 id="modal-title">${title}</h2>${btn('close',icon('close'),'icon-button','aria-label="بستن"')}</div>${form?`<form id="editor" data-form="${form}" data-id="${h(id)}" class="form-grid">${content}<p class="form-error full" role="alert"></p><div class="modal-actions full"><button type="submit" class="button primary">ذخیره</button>${btn('close','انصراف','button')}</div></form>`:content}`;if(!modal.open)modal.showModal();}
function editor(kind,id){const account=state.accounts.find(a=>a.id===id),trade=state.trades.find(t=>t.id===id),note=state.notes.find(t=>t.id===id),cost=state.costs.find(t=>t.id===id),step=state.steps.find(t=>t.id===id);if(kind==='account'){const a=account||{name:'',type:'دمو',broker:'',deposit:'',date:dayKey()};openDialog(account?'ویرایش حساب':'حساب معاملاتی جدید',field('نام حساب','name',a.name,'text','required maxlength="200"')+`<label>نوع حساب<select name="type">${['واقعی','دمو','پراپ'].map(v=>`<option ${a.type===v?'selected':''}>${v}</option>`).join('')}</select></label>`+field('سپرده اولیه (USD)','deposit',a.deposit,'number','min="0" max="1000000000000" step="any" required')+field('بروکر','broker',a.broker,'text','required maxlength="200"')+field('تاریخ ایجاد (میلادی)','date',a.date,'date','required'),'account',id);}
if(kind==='trade'){if(!state.accounts.length){toast('ابتدا یک حساب معاملاتی بسازید.');editor('account');return;}const t=trade||{account:state.accounts[0].id,date:dayKey(),symbol:state.symbols[0]||'',time:clockAt(new Date(),-4).slice(0,5),result:'TP',pnl:'',note:'',image:''};openDialog(trade?'جزئیات و ویرایش معامله':'ثبت معامله جدید',`<label>حساب<select name="account" required>${state.accounts.map(a=>`<option value="${h(a.id)}" ${a.id===t.account?'selected':''}>${h(a.name)}</option>`).join('')}</select></label>`+field('تاریخ معامله (میلادی)','date',t.date,'date','required')+`<label>نماد؛ انتخاب یا تایپ نماد جدید<input name="symbol" list="symbol-list" value="${h(t.symbol)}" required maxlength="30" dir="ltr"><datalist id="symbol-list">${state.symbols.map(s=>`<option value="${h(s)}"></option>`).join('')}</datalist></label>`+field('ساعت نیویورک (UTC−4 ثابت)','time',t.time,'time','required')+`<label>نتیجه<select name="result"><option value="TP" ${t.result==='TP'?'selected':''}>TP — موفق</option><option value="SL" ${t.result==='SL'?'selected':''}>SL — ناموفق</option></select></label>`+field('مقدار سود یا زیان، بدون علامت (USD)','amount',t.pnl===''?'':Math.abs(t.pnl),'number','min="0" max="1000000000000" step="any" required')+textarea('توضیحات معامله','note',t.note,'maxlength="10000"')+`<label class="full">تصویر معامله (PNG، JPEG یا WebP، حداکثر ۲ مگابایت)<input name="image" type="file" accept="image/png,image/jpeg,image/webp"></label>${t.image?`<div class="full"><img class="attachment-preview" src="${h(t.image)}" alt="تصویر معامله"><label class="check-row"><input type="checkbox" name="removeImage">حذف تصویر فعلی</label></div>`:''}`,'trade',id);}
if(kind==='note')openDialog(note?'ویرایش یادداشت':'اصول، قواعد و یادگیری',field('تاریخ یادداشت','date',note?.date||dayKey(),'date','required')+textarea('متن یادداشت','text',note?.text||'','required maxlength="10000"'),'note',id);
if(kind==='cost')openDialog(cost?'ویرایش هزینه':'ثبت هزینه',field('عنوان هزینه','title',cost?.title||'','text','required maxlength="200"')+field('مبلغ (USD)','amount',cost?.amount??'','number','required min="0" max="1000000000000" step="any"')+field('تاریخ','date',cost?.date||dayKey(),'date','required'),'cost',id);
if(kind==='step')openDialog(step?'ویرایش مرحله':'مرحله جدید در پلن',textarea('شرح مرحله','text',step?.text||'','required maxlength="500"'),'step',id);
}
function settings(){openDialog('تنظیمات و نگهداری اطلاعات',`<form id="settings-form" class="form-grid"><label class="check-row full"><input type="checkbox" name="autoRate" ${state.settings.autoRate!==false?'checked':''}>دریافت خودکار نرخ دلار از وب، هر ۵ دقیقه</label>${field('نرخ دستی تومان (فقط با خاموش‌کردن حالت خودکار)','rate',state.settings.rate||'','number','min="0" max="1000000000000" step="any"')}<p class="micro">${rateStatus()}<br>منبع عمومی: priceto.day؛ مبلغ ریالی بر ۱۰ تقسیم می‌شود. در خطا، نرخ قبلی حفظ و زمان آن نمایش داده می‌شود.</p>${field('مسیر API نرخ‌ها روی همین دامنه (اختیاری)','feed',state.settings.feed,'text','placeholder="./api/quotes" maxlength="500"')}<p class="micro">اتصال زنده به سرویس ارائه‌دهنده نیاز دارد. ساختار پاسخ در راهنما آمده است؛ کلید محرمانه را اینجا وارد نکنید.</p><button class="button primary">ذخیره تنظیمات</button></form><hr><h3>نسخهٔ پشتیبان</h3><p class="muted">اطلاعات در همین مرورگر نگهداری می‌شود؛ همگام‌سازی ابری ندارد. قبل از پاک‌کردن مرورگر پشتیبان بگیرید. فایل پشتیبان شامل تصویر معاملات و رمزگذاری‌نشده است.</p><div class="inline-actions">${btn('backup',icon('download')+' دریافت پشتیبان','button secondary')}<label class="button">بازیابی پشتیبان<input id="import-backup" type="file" accept=".json,application/json" hidden></label></div><p class="micro">بازیابی پس از تأیید، تمام اطلاعات فعلی را جایگزین می‌کند.</p><hr><p class="muted">نصب در Safari آیفون: Share ← Add to Home Screen. در دسکتاپ از گزینهٔ نصب مرورگر استفاده کنید. نصب و آفلاین به HTTPS نیاز دارد.</p><a href="./guide.html" target="_blank" rel="noopener" class="text-button">راهنمای کامل</a>`);}
function symbols(){openDialog('مدیریت نمادها',`<p class="muted">ویرایش نماد، معاملات قبلی آن را هم به‌روز می‌کند. نماد دارای معامله قابل حذف نیست.</p><form id="symbol-add" class="inline-actions"><input name="symbol" aria-label="نماد جدید" placeholder="BTCUSD" maxlength="30" required dir="ltr"><button class="button secondary">افزودن</button></form><div class="symbol-list">${state.symbols.map(s=>`<div><bdi>${h(s)}</bdi><span>${btn('rename-symbol','ویرایش','small-button',`data-symbol="${h(s)}"`)}${btn('delete-symbol','حذف','small-button',`data-symbol="${h(s)}"`)}</span></div>`).join('')}</div>`);}
async function imageData(file){if(!['image/png','image/jpeg','image/webp'].includes(file.type)||file.size>2*1024*1024)throw Error('یک تصویر PNG، JPEG یا WebP تا ۲ مگابایت انتخاب کنید.');const bytes=new Uint8Array(await file.slice(0,12).arrayBuffer());const signature=file.type==='image/png'?bytes[0]===137&&bytes[1]===80&&bytes[2]===78&&bytes[3]===71:file.type==='image/jpeg'?bytes[0]===255&&bytes[1]===216&&bytes[2]===255:String.fromCharCode(...bytes.slice(0,4))==='RIFF'&&String.fromCharCode(...bytes.slice(8,12))==='WEBP';if(!signature)throw Error('محتوای فایل با نوع تصویر مطابقت ندارد.');return new Promise((resolve,reject)=>{const reader=new FileReader();reader.onload=()=>resolve(reader.result);reader.onerror=()=>reject(Error('تصویر قابل خواندن نیست.'));reader.readAsDataURL(file);});}
async function submitEditor(form){const values=Object.fromEntries(new FormData(form));const id=form.dataset.id||Array.from(crypto.getRandomValues(new Uint8Array(16)),b=>b.toString(16).padStart(2,'0')).join(''),kind=form.dataset.form;let row,collection;if(kind==='account'){collection='accounts';row={id,name:values.name.trim(),type:values.type,deposit:Number(values.deposit),broker:values.broker.trim(),date:values.date};if(!row.name||!row.broker)throw Error('نام حساب و بروکر را وارد کنید.');}
if(kind==='trade'){collection='trades';let image=state.trades.find(t=>t.id===id)?.image||'';if(values.removeImage)image='';if(values.image?.size)image=await imageData(values.image);row={id,account:values.account,date:values.date,time:values.time,symbol:values.symbol.trim().toUpperCase(),result:values.result,pnl:Math.abs(Number(values.amount))*(values.result==='SL'?-1:1),note:values.note.trim(),image};}
if(kind==='note'){collection='notes';row={id,section:state.notes.find(n=>n.id===id)?.section||tab,date:values.date,text:values.text.trim()};}
if(kind==='cost'){collection='costs';row={id,title:values.title.trim(),amount:Number(values.amount),date:values.date};}
if(kind==='step'){collection='steps';row={id,text:values.text.trim()};}
if((row.text!==undefined&&!row.text)||(row.title!==undefined&&!row.title))throw Error('متن نمی‌تواند خالی باشد.');await commit(s=>{if(kind==='trade'&&!s.symbols.includes(row.symbol))s.symbols.push(row.symbol);const index=s[collection].findIndex(v=>v.id===id);if(index<0)s[collection].push(row);else s[collection][index]=row;});modal.close();toast('با موفقیت ذخیره شد.');}
function report(type,format){let headers,rows,title;const unit=currencyTitle();if(type==='trades'){const trades=filterTrades(state.trades,filters),st=statistics(trades);title=`معاملات ${filters.start} تا ${filters.end} | تعداد ${st.count} | TP ${st.wins} | SL ${st.losses} | موفقیت ${st.winRate.toFixed(1)}٪ | خالص ${plainMoney(st.pnl).toFixed(2)} ${unit}`;headers=['حساب','تاریخ','ساعت نیویورک UTC−4','نماد','نتیجه',`سود/زیان (${unit})`,'یادداشت','تصویر پیوست'];rows=[...trades].sort(sortTrades).map(t=>[accountName(t.account),t.date,t.time,t.symbol,t.result,plainMoney(t.pnl),t.note,t.image?'دارد؛ در فایل پشتیبان موجود است':'ندارد']);}if(type==='notes'){title='اصول، قواعد و یادگیری — '+SECTIONS.find(s=>s[0]===tab)[1];headers=['تاریخ میلادی','تاریخ شمسی','یادداشت'];rows=state.notes.filter(n=>n.section===tab).sort((a,b)=>b.date.localeCompare(a.date)).map(n=>[n.date,persianDate(n.date),n.text]);}if(type==='accounts'){title='گزارش حساب‌های معاملاتی';headers=['حساب','نوع','بروکر','تاریخ',`سپرده (${unit})`,`موجودی (${unit})`,'بازده (%)'];rows=state.accounts.map(a=>{const st=accountStats(a,state.trades);return [a.name,a.type,a.broker,a.date,plainMoney(a.deposit),plainMoney(st.balance),st.percent];});}if(type==='costs'){title='گزارش سرمایه‌گذاری و هزینه‌ها';headers=['تاریخ','عنوان',`هزینه (${unit})`];rows=state.costs.map(c=>[c.date,c.title,plainMoney(c.amount)]);rows.push(['','مجموع',state.costs.reduce((s,c)=>s+plainMoney(c.amount),0)]);}if(type==='steps'){title='پلن معاملاتی';headers=['مرحله','شرح'];rows=state.steps.map((s,i)=>[i+1,s.text]);}if(state.settings.currency==='IRT'&&state.settings.rate)title+=` | نرخ تبدیل: ${state.settings.rate} تومان؛ ثبت ${state.settings.rateAt}`;if(!rows.length){toast('داده‌ای برای خروجی وجود ندارد.');return;}exportReport(format,title,headers,rows);if(format==='pdf')toast('در پنجرهٔ چاپ، گزینهٔ ذخیره به‌صورت PDF را انتخاب کنید.');}
async function refreshFeed(silent=false){if(feedBusy)return;if(!state.settings.feed){if(!silent){const frame=document.getElementById('market-frame');const theme=state.settings.theme==='dark'?'dark':'light';if(frame)frame.src='./market.html?theme='+theme+'&refresh='+Date.now();toast(navigator.onLine?'نمایش آنلاین بازار دوباره بارگذاری شد.':'برای نرخ آنلاین به اینترنت وصل شوید.');}return;}feedBusy=true;const controller=new AbortController(),timeout=setTimeout(()=>controller.abort(),10000);try{const url=new URL(state.settings.feed,location.href);if(url.origin!==location.origin||url.username||url.password)throw Error('فقط مسیر API روی همین دامنه مجاز است.');const response=await fetch(url,{cache:'no-store',signal:controller.signal,credentials:'same-origin'});if(!response.ok)throw Error('منبع نرخ در دسترس نیست.');const data=validateFeed(await response.json());await commit(s=>{s.quotes=data.quotes;s.quotesAt=data.timestamp;if(data.rate&&s.settings.autoRate===false){s.settings.rate=data.rate;s.settings.rateAt=data.timestamp;s.settings.rateSource='custom';}});if(!silent)toast('دادهٔ منبع دریافت شد؛ زمان داده را بررسی کنید.');}catch(error){if(!silent)toast(error.message==='Failed to fetch'?'دریافت نرخ ناموفق بود؛ اتصال و منبع را بررسی کنید.':error.message);}finally{clearTimeout(timeout);feedBusy=false;}}
async function action(el){const a=el.dataset.action,id=el.dataset.id;if(a==='close')modal.close();else if(a==='settings')settings();else if(a==='new-trade'||a==='edit-trade')editor('trade',id);else if(a==='new-account'||a==='edit-account')editor('account',id);else if(a==='new-note'||a==='edit-note')editor('note',id);else if(a==='new-cost'||a==='edit-cost')editor('cost',id);else if(a==='new-step'||a==='edit-step')editor('step',id);else if(a==='symbols')symbols();else if(a==='theme'){await commit(s=>s.settings.theme=s.settings.theme==='dark'?'light':'dark');}else if(a==='refresh-rate')await refreshDollarRate(true);else if(a==='currency'){if(state.settings.currency==='USD'&&!state.settings.rate){toast('برای تبدیل، نرخ دلار به تومان را وارد کنید.');settings();return;}await commit(s=>s.settings.currency=s.settings.currency==='USD'?'IRT':'USD');}else if(a==='range'){filters={...filters,...dateRange(el.dataset.range)};render();}else if(a==='delete'){const kind=el.dataset.kind;if(!['accounts','trades','notes','steps','costs'].includes(kind))return;if(kind==='accounts'&&state.trades.some(t=>t.account===id)){toast('حساب دارای معامله حذف نمی‌شود؛ ابتدا معاملات مرتبط را مدیریت کنید.');return;}if(confirm('این مورد حذف شود؟ این کار قابل بازگشت نیست.'))await commit(s=>s[kind]=s[kind].filter(v=>v.id!==id));}else if(a==='move-step'){await commit(s=>{const i=s.steps.findIndex(v=>v.id===id);if(i>0)[s.steps[i-1],s.steps[i]]=[s.steps[i],s.steps[i-1]];});}else if(a==='export')report(el.dataset.type,el.dataset.format);else if(a==='backup')download(JSON.stringify(state,null,2),`MET-backup-${dayKey()}.json`,'application/json');else if(a==='refresh')await refreshFeed();else if(a==='delete-symbol'){const symbol=el.dataset.symbol;if(state.trades.some(t=>t.symbol===symbol)){toast('این نماد معاملهٔ ثبت‌شده دارد و قابل حذف نیست.');return;}if(confirm(`نماد ${symbol} حذف شود؟`)){await commit(s=>s.symbols=s.symbols.filter(v=>v!==symbol));symbols();}}else if(a==='rename-symbol'){const old=el.dataset.symbol,value=prompt('نام جدید نماد',old);if(!value)return;const symbol=value.trim().toUpperCase();if(!/^[A-Z0-9._/-]{1,30}$/.test(symbol))throw Error('نماد معتبر نیست.');if(symbol!==old&&state.symbols.includes(symbol))throw Error('این نماد وجود دارد.');await commit(s=>{s.symbols=s.symbols.map(v=>v===old?symbol:v);s.trades.forEach(t=>{if(t.symbol===old)t.symbol=symbol;});});symbols();}}
document.addEventListener('click',event=>{const nav=event.target.closest('[data-tab]');if(nav){tab=nav.dataset.tab;location.hash=tab;render();document.getElementById('main').focus();return;}const el=event.target.closest('[data-action]');if(el){if(el.closest('form'))event.preventDefault();action(el).catch(e=>toast(e.message||'عملیات انجام نشد.'));}});
document.addEventListener('submit',async event=>{event.preventDefault();const form=event.target,button=form.querySelector('[type="submit"],button:not([type])');if(button)button.disabled=true;try{if(form.id==='editor')await submitEditor(form);if(form.id==='filters'){const data=Object.fromEntries(new FormData(form));if(data.start>data.end)throw Error('تاریخ شروع باید قبل از پایان باشد.');filters=data;render();}if(form.id==='risk'){const data=Object.fromEntries(new FormData(form));document.getElementById('risk-result').innerHTML=`حداکثر زیان برنامه‌ریزی‌شده: <strong>${money(riskAmount(Number(data.balance),Number(data.percent)))}</strong>`;}if(form.id==='settings-form'){const values=Object.fromEntries(new FormData(form)),feed=values.feed.trim();if(feed){const url=new URL(feed,location.href);if(url.origin!==location.origin||url.username||url.password||!['http:','https:'].includes(url.protocol))throw Error('منبع باید یک مسیر API روی همین دامنه باشد.');}await commit(s=>{s.settings.autoRate=values.autoRate==='on';const rate=Number(values.rate);if(!s.settings.autoRate&&(rate!==s.settings.rate||s.settings.rateSource!=='manual')){s.settings.rate=rate;s.settings.rateAt=new Date().toISOString();s.settings.rateSource='manual';}s.settings.feed=feed;if(!s.settings.rate)s.settings.currency='USD';});modal.close();rateError='';toast('تنظیمات ذخیره شد.');if(state.settings.autoRate)refreshDollarRate();}if(form.id==='symbol-add'){const symbol=new FormData(form).get('symbol').trim().toUpperCase();if(!/^[A-Z0-9._/-]{1,30}$/.test(symbol))throw Error('نماد را با حروف لاتین، عدد، نقطه، خط تیره یا اسلش وارد کنید.');if(state.symbols.includes(symbol))throw Error('این نماد از قبل وجود دارد.');await commit(s=>s.symbols.push(symbol));symbols();}}catch(e){const err=form.querySelector('.form-error');if(err)err.textContent=e.message;else toast(e.message||'ذخیره نشد؛ فضای ذخیره‌سازی را بررسی کنید.');}finally{if(button)button.disabled=false;}});
document.addEventListener('change',async event=>{const el=event.target;try{if(el.dataset.check){const checked=el.checked;await commit(s=>{if(s.checklistDate!==dayKey())s.checklist.forEach(c=>c.done=false);s.checklistDate=dayKey();s.checklist.find(c=>c.id===el.dataset.check).done=checked;});}if(el.id==='import-backup'){const file=el.files[0];if(!file)return;if(file.size>50*1024*1024)throw Error('فایل پشتیبان باید کمتر از ۵۰ مگابایت باشد.');const incoming=validateState(JSON.parse(await file.text()));if(incoming.settings.feed){const url=new URL(incoming.settings.feed,location.href);if(url.origin!==location.origin||url.username||url.password)throw Error('مسیر منبع نرخ در پشتیبان مجاز نیست.');}if(!confirm('تمام اطلاعات فعلی با اطلاعات این فایل جایگزین شود؟ ابتدا از اطلاعات فعلی پشتیبان گرفته‌اید؟'))return;await commit(s=>Object.assign(s,incoming));modal.close();toast('پشتیبان با موفقیت بازیابی شد.');}}catch(e){toast(e.message||'بازیابی یا ذخیره انجام نشد.');if(el.dataset.check)render();}finally{if(el.id==='import-backup')el.value='';}});
window.addEventListener('hashchange',()=>{const next=location.hash.slice(1);if(SECTIONS.some(s=>s[0]===next)){tab=next;if(state)render();}});
for(const event of ['online','offline'])window.addEventListener(event,()=>{const el=document.getElementById('network-label');if(el)el.textContent=navigator.onLine?'آمادهٔ ثبت':'حالت آفلاین';if(state){updateRateStatus();if(event==='online')refreshDollarRate();}});
try{state=await load();const initial=location.hash.slice(1);if(SECTIONS.some(s=>s[0]===initial))tab=initial;render();window.metReady=true;refreshDollarRate();setInterval(()=>{if(!document.hidden)refreshDollarRate();},300000);setInterval(updateClock,1000);setInterval(()=>{if(!document.hidden&&navigator.onLine)refreshFeed(true);},60000);if('serviceWorker' in navigator)navigator.serviceWorker.register('./sw.js').catch(()=>toast('ذخیرهٔ آفلاین برنامه فعال نشد؛ اتصال و HTTPS را بررسی کنید.'));}catch(error){window.metReady=true;root.innerHTML=`<section class="startup-error"><h1>دسترسی به دفتر معاملاتی ممکن نیست</h1><p>مجوز ذخیره‌سازی مرورگر و فضای خالی را بررسی کنید. اطلاعات موجود حذف نشده است.</p><p>${h(error.message)}</p><button class="button" onclick="location.reload()">تلاش دوباره</button></section>`;}

})().catch(function(error){ if(window.metBootError) window.metBootError(error); else setTimeout(function(){throw error;},0); });
